// Reimplementation of argparse help layout for this specific parser.
const PROG = 'test19_executable';

function termWidth() {
  const raw = process.env.COLUMNS;
  let cols = 0;
  if (raw !== undefined) {
    // int(str) semantics: optional surrounding whitespace, optional sign, digits only
    if (/^\s*[+-]?\d+\s*$/.test(raw)) cols = parseInt(raw.trim(), 10);
  }
  if (cols <= 0) cols = 80; // stdout not a tty -> shutil fallback
  return cols;
}

// textwrap.wrap on whitespace-collapsed text, greedy, width>=1
function wrap(text, width) {
  const words = text.split(/\s+/).filter(Boolean);
  const lines = [];
  let cur = '';
  for (const w of words) {
    if (cur === '') { cur = w; continue; }
    if (cur.length + 1 + w.length <= width) cur += ' ' + w;
    else { lines.push(cur); cur = w; }
  }
  if (cur !== '') lines.push(cur);
  return lines;
}

function buildHelp() {
  const cols = termWidth();
  const width = cols - 2;                       // HelpFormatter._width
  const maxHelpPosition = Math.min(24, Math.max(width - 20, 4));
  const actionMaxLength = 12;                   // max(len(invocation)) + indent = 10 + 2
  const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);
  const helpWidth = Math.max(width - helpPosition, 11);
  const actionWidth = helpPosition - 2 - 2;     // - current_indent - 2

  const out = [];

  // ---- usage ----
  const prefix = 'usage: ';
  const optParts = ['[-h]', '--k1 K1', '--v1 V1', '--k2 K2', '--v2 V2'];
  const oneLine = prefix + PROG + ' ' + optParts.join(' ');
  if (oneLine.length <= width) {
    out.push(oneLine);
  } else {
    const indentLen = prefix.length + PROG.length + 1; // align after prog
    if (indentLen + Math.max(...optParts.map(p => p.length)) <= width) {
      // wrap parts to width - indentLen, first line joined to "usage: prog"
      const lines = packParts(optParts, width - indentLen);
      out.push(prefix + PROG + ' ' + lines[0]);
      for (let i = 1; i < lines.length; i++) out.push(' '.repeat(indentLen) + lines[i]);
    } else {
      // prog on its own line, opts indented by len(prefix)
      const ind = ' '.repeat(prefix.length);
      const lines = packParts(optParts, Math.max(width - prefix.length, 11));
      out.push(prefix + PROG);
      for (const l of lines) out.push(ind + l);
    }
  }
  out.push('');

  // ---- options section ----
  out.push('options:');
  const helpLines = wrap('show this help message and exit', helpWidth);
  const inv = '-h, --help';
  if (inv.length <= actionWidth) {
    out.push('  ' + inv.padEnd(actionWidth) + '  ' + helpLines[0]);
    for (let i = 1; i < helpLines.length; i++) out.push(' '.repeat(helpPosition) + helpLines[i]);
  } else {
    out.push('  ' + inv);
    for (const l of helpLines) out.push(' '.repeat(helpPosition) + l);
  }
  for (const n of ['--k1 K1', '--v1 V1', '--k2 K2', '--v2 V2']) out.push('  ' + n);

  return out.join('\n') + '\n';
}

// greedy pack of atomic parts into lines of at most w chars
function packParts(parts, w) {
  const lines = [];
  let cur = '';
  for (const p of parts) {
    if (cur === '') { cur = p; continue; }
    if (cur.length + 1 + p.length <= w) cur += ' ' + p;
    else { lines.push(cur); cur = p; }
  }
  if (cur !== '') lines.push(cur);
  return lines;
}

process.stdout.write(buildHelp());

const PROG = 'test19_executable';

function termWidth() {
  const raw = process.env.COLUMNS;
  let cols = 0;
  if (raw !== undefined && /^\s*[+-]?\d+\s*$/.test(raw)) cols = parseInt(raw.trim(), 10);
  if (cols <= 0) cols = 80;
  return cols;
}

function wrap(text, width) {
  const words = text.split(/\s+/).filter(Boolean);
  const lines = []; let cur = '';
  for (const w of words) {
    if (cur === '') { cur = w; continue; }
    if (cur.length + 1 + w.length <= width) cur += ' ' + w;
    else { lines.push(cur); cur = w; }
  }
  if (cur !== '') lines.push(cur);
  return lines;
}

// faithful port of argparse HelpFormatter._format_usage's get_lines
function getLines(parts, indent, textWidth, prefix) {
  const lines = []; let line = [];
  let lineLen = (prefix !== undefined ? prefix.length : indent.length) - 1;
  for (const part of parts) {
    if (lineLen + 1 + part.length > textWidth && line.length) {
      lines.push(indent + line.join(' '));
      line = []; lineLen = indent.length - 1;
    }
    line.push(part); lineLen += 1 + part.length;
  }
  if (line.length) lines.push(indent + line.join(' '));
  if (prefix !== undefined) lines[0] = lines[0].slice(indent.length);
  return lines;
}

function buildHelp() {
  const cols = termWidth();
  const width = cols - 2;
  const textWidth = width;                     // current_indent == 0
  const prefix = 'usage: ';
  const optParts = ['[-h]', '--k1', 'K1', '--v1', 'V1', '--k2', 'K2', '--v2', 'V2'];
  const flat = prefix + PROG + ' ' + '[-h] --k1 K1 --v1 V1 --k2 K2 --v2 V2';
  const out = [];

  if (flat.length <= textWidth) {
    out.push(flat);
  } else if (prefix.length + PROG.length <= 0.75 * textWidth) {
    const indent = ' '.repeat(prefix.length + PROG.length + 1);
    const lines = getLines([PROG, ...optParts], indent, textWidth, prefix);
    out.push(prefix + lines.join('\n'));
  } else {
    const indent = ' '.repeat(prefix.length);
    const lines = getLines(optParts, indent, textWidth);
    out.push(prefix + [PROG, ...lines].join('\n'));
  }
  out.push('');

  // ---- options section: the answer to the open question ----
  const maxHelpPosition = Math.min(24, Math.max(width - 20, 4));
  const helpPosition = Math.min(12 + 2, maxHelpPosition);   // action_max_length == 12
  const helpWidth = Math.max(width - helpPosition, 11);
  const actionWidth = helpPosition - 2 - 2;

  out.push('options:');
  const helpLines = wrap('show this help message and exit', helpWidth);
  const inv = '-h, --help';
  if (inv.length <= actionWidth) {
    out.push('  ' + inv.padEnd(actionWidth) + '  ' + helpLines[0]);
    for (let i = 1; i < helpLines.length; i++) out.push(' '.repeat(helpPosition) + helpLines[i]);
  } else {
    out.push('  ' + inv);
    for (const l of helpLines) out.push(' '.repeat(helpPosition) + l);
  }
  for (const n of ['--k1 K1', '--v1 V1', '--k2 K2', '--v2 V2']) out.push('  ' + n);

  return out.join('\n') + '\n';
}

process.stdout.write(buildHelp());
